#include <bits/stdc++.h>
using namespace std;

/*
We model each futon as a domino occupying two adjacent cells.
For each domino, one end is "head" and the other is "feet".

Condition:
No person's feet may be adjacent (4-neighbor) to another person's head.

Input format is not explicitly shown in the prompt, but this classic problem is:
H W
grid of H strings, where equal letters denote the two cells of one futon.

Each futon label appears exactly twice in adjacent cells.

For every futon, there are two possible orientations (which of its two cells is head).
We must determine whether there exists an assignment of head/feet for all futons
such that no feet cell is adjacent to any other futon's head cell.

This is a 2-SAT problem.

For each futon i, variable xi:
  xi = 0 -> first stored cell is head, second is feet
  xi = 1 -> first stored cell is feet, second is head

For every adjacent pair of cells belonging to different futons, the assignment
(feet on one side, head on the other side) is forbidden.
This gives a clause of the form !(A_is_feet && B_is_head),
which translates to (!A_is_feet) OR (!B_is_head), i.e. a 2-SAT clause.

We build implications and test satisfiability with SCC.

Output:
"Yes" if possible, otherwise "No".
*/

struct TwoSAT {
    int n;
    vector<vector<int>> g, rg;
    TwoSAT(int n = 0): n(n), g(2*n), rg(2*n) {}

    // literal: var x is val (false/true)
    int id(int x, bool val) { return 2*x + (val ? 1 : 0); }

    void addImp(int a, int b) {
        g[a].push_back(b);
        rg[b].push_back(a);
    }

    void addOr(int x, bool xv, int y, bool yv) {
        // (x=xv) OR (y=yv)
        addImp(id(x, !xv), id(y, yv));
        addImp(id(y, !yv), id(x, xv));
    }

    // forbid (x=xv) AND (y=yv)
    void forbidBoth(int x, bool xv, int y, bool yv) {
        addOr(x, !xv, y, !yv);
    }

    bool satisfiable() {
        int N = 2*n;
        vector<int> vis(N, 0), order;
        function<void(int)> dfs1 = [&](int v) {
            vis[v] = 1;
            for (int to : g[v]) if (!vis[to]) dfs1(to);
            order.push_back(v);
        };
        for (int i = 0; i < N; i++) if (!vis[i]) dfs1(i);

        vector<int> comp(N, -1);
        function<void(int,int)> dfs2 = [&](int v, int c) {
            comp[v] = c;
            for (int to : rg[v]) if (comp[to] == -1) dfs2(to, c);
        };

        int c = 0;
        for (int i = N - 1; i >= 0; i--) {
            int v = order[i];
            if (comp[v] == -1) dfs2(v, c++);
        }

        for (int i = 0; i < n; i++) {
            if (comp[2*i] == comp[2*i+1]) return false;
        }
        return true;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int H, W;
    cin >> H >> W;
    vector<string> S(H);
    for (int i = 0; i < H; i++) cin >> S[i];

    map<char, vector<pair<int,int>>> pos;
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            pos[S[i][j]].push_back({i, j});
        }
    }

    vector<char> labels;
    for (auto &kv : pos) labels.push_back(kv.first);

    int n = (int)labels.size();
    map<char, int> idx;
    for (int i = 0; i < n; i++) idx[labels[i]] = i;

    // cells[i][0], cells[i][1]
    vector<array<pair<int,int>,2>> cells(n);
    for (int i = 0; i < n; i++) {
        auto &v = pos[labels[i]];
        if (v.size() != 2) {
            cout << "No\n";
            return 0;
        }
        cells[i][0] = v[0];
        cells[i][1] = v[1];
    }

    // Validate adjacency of each futon and map each occupied cell to (futon, endpoint 0/1)
    vector<vector<pair<int,int>>> owner(H, vector<pair<int,int>>(W, {-1, -1}));
    for (int i = 0; i < n; i++) {
        auto [r1, c1] = cells[i][0];
        auto [r2, c2] = cells[i][1];
        if (abs(r1 - r2) + abs(c1 - c2) != 1) {
            cout << "No\n";
            return 0;
        }
        owner[r1][c1] = {i, 0};
        owner[r2][c2] = {i, 1};
    }

    TwoSAT sat(n);

    auto isFeet = [&](int endpoint, bool xval) -> bool {
        // x=0: endpoint0=head, endpoint1=feet
        // x=1: endpoint0=feet, endpoint1=head
        return (endpoint == 0 ? xval : !xval);
    };

    auto isHead = [&](int endpoint, bool xval) -> bool {
        return !isFeet(endpoint, xval);
    };

    // For each adjacent pair of cells from different futons,
    // forbid (A cell is feet) AND (B cell is head), and vice versa will be handled
    // when iterating that edge direction as a separate ordered interpretation is unnecessary:
    // the custom specifically forbids feet adjacent to another's head, so for each unordered
    // adjacent pair we must forbid both directional bad patterns.
    const int dr[4] = {-1, 1, 0, 0};
    const int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < H; r++) {
        for (int c = 0; c < W; c++) {
            auto [a, ea] = owner[r][c];
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d], nc = c + dc[d];
                if (nr < 0 || nr >= H || nc < 0 || nc >= W) continue;
                auto [b, eb] = owner[nr][nc];
                if (a == -1 || b == -1 || a == b) continue;

                // To avoid duplicating identical unordered edge handling too much,
                // process only one direction for the pair of cells.
                if (make_pair(r, c) > make_pair(nr, nc)) continue;

                // Forbid:
                // (cell a = feet) AND (cell b = head)
                // and
                // (cell a = head) AND (cell b = feet)

                for (int xa = 0; xa <= 1; xa++) {
                    for (int xb = 0; xb <= 1; xb++) {
                        bool aFeet = isFeet(ea, xa);
                        bool aHead = !aFeet;
                        bool bFeet = isFeet(eb, xb);
                        bool bHead = !bFeet;

                        if (aFeet && bHead) {
                            sat.forbidBoth(a, xa, b, xb);
                        }
                        if (aHead && bFeet) {
                            sat.forbidBoth(a, xa, b, xb);
                        }
                    }
                }
            }
        }
    }

    cout << (sat.satisfiable() ? "Yes" : "No") << '\n';
    return 0;
}

