    char g[MAXH][MAXW];
    for (int i = 0; i < H; i++) {
        scanf("%s", g[i]);
    }

    /* 
       Interpretation:
       Each futon occupies exactly two adjacent cells and is represented by
       two symbols: 'h' (head) and 'f' (foot).
       We must check whether there exists any adjacency where a foot cell is
       adjacent (4-neighbor) to a head cell of another futon.

       We ignore the head-foot adjacency inside the same futon.
    */

    int dr[4] = {-1, 1, 0, 0};
    int dc[4] = {0, 0, -1, 1};

    for (int r = 0; r < H; r++) {
        for (int c = 0; c < W; c++) {
            if (g[r][c] != 'f') continue;

            /* Find the head belonging to this same futon */
            int own_hr = -1, own_hc = -1;
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (0 <= nr && nr < H && 0 <= nc && nc < W && g[nr][nc] == 'h') {
                    own_hr = nr;
                    own_hc = nc;
                    break;
                }
            }

            /* Check all adjacent heads; any except own head is bad */
            for (int k = 0; k < 4; k++) {
                int nr = r + dr[k], nc = c + dc[k];
                if (0 <= nr && nr < H && 0 <= nc && nc < W && g[nr][nc] == 'h') {
                    if (!(nr == own_hr && nc == own_hc)) {
                        printf("No\n");
                        return 0;
                    }
                }
            }
        }
    }

    printf("Yes\n");
    return 0;
}

