import sys

def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return

    h = int(data[0])
    w = int(data[1])
    grid = data[2:2 + h]

    # Collect all futons as unordered adjacent pairs of '#'
    futons = []
    used = [[False] * w for _ in range(h)]

    dirs = [(1, 0), (-1, 0), (0, 1), (0, -1)]

    for i in range(h):
        for j in range(w):
            if grid[i][j] != '#' or used[i][j]:
                continue

            neigh = []
            for di, dj in dirs:
                ni, nj = i + di, j + dj
                if 0 <= ni < h and 0 <= nj < w and grid[ni][nj] == '#':
                    neigh.append((ni, nj))

            # Each futon occupies exactly two adjacent cells
            if len(neigh) != 1:
                print("No")
                return

            ni, nj = neigh[0]
            if used[ni][nj]:
                print("No")
                return

            used[i][j] = True
            used[ni][nj] = True
            futons.append(((i, j), (ni, nj)))

    # Check whether we can assign head/feet directions so that
    # no feet cell is adjacent (4-neighbor) to any head cell of another futon.
    n = len(futons)
    if n == 0:
        print("Yes")
        return

    # 2-SAT:
    # variable x_i = 0 means first cell is head, second is feet
    # variable x_i = 1 means first cell is feet, second is head
    #
    # For every adjacent cells belonging to different futons, forbid
    # assignments where one is feet and the other is head.

    def is_head(var_val, endpoint_idx):
        # endpoint_idx 0 for first cell, 1 for second cell
        # x=0 => first=head second=feet
        # x=1 => first=feet second=head
        return (var_val == 0 and endpoint_idx == 0) or (var_val == 1 and endpoint_idx == 1)

    def lit_id(i, val):
        # node for x_i = val
        return 2 * i + val

    def add_implication(g, rg, a, b):
        g[a].append(b)
        rg[b].append(a)

    def add_clause_or(g, rg, a_var, a_val, b_var, b_val):
        # (x_a = a_val) OR (x_b = b_val)
        # equivalent to (!A -> B) and (!B -> A)
        A = lit_id(a_var, a_val)
        notA = lit_id(a_var, 1 - a_val)
        B = lit_id(b_var, b_val)
        notB = lit_id(b_var, 1 - b_val)
        add_implication(g, rg, notA, B)
        add_implication(g, rg, notB, A)

    cell_owner = {}
    for idx, (a, b) in enumerate(futons):
        cell_owner[a] = (idx, 0)
        cell_owner[b] = (idx, 1)

    m = 2 * n
    g = [[] for _ in range(m)]
    rg = [[] for _ in range(m)]

    for i in range(h):
        for j in range(w):
            if grid[i][j] != '#':
                continue
            fi, ei = cell_owner[(i, j)]
            for di, dj in [(1, 0), (0, 1)]:  # avoid double counting
                ni, nj = i + di, j + dj
                if not (0 <= ni < h and 0 <= nj < w):
                    continue
                if grid[ni][nj] != '#':
                    continue
                fj, ej = cell_owner[(ni, nj)]
                if fi == fj:
                    continue

                # Forbid assignments where cell(fi,ei) is feet and cell(fj,ej) is head.
                # That forbidden pair corresponds to one assignment (xi=a, xj=b),
                # so add clause (xi != a) OR (xj != b).
                bad = []
                for xi in (0, 1):
                    for xj in (0, 1):
                        feet_i = not is_head(xi, ei)
                        head_j = is_head(xj, ej)
                        if feet_i and head_j:
                            bad.append((xi, xj))
                # exactly one bad pair
                for xi, xj in bad:
                    add_clause_or(g, rg, fi, 1 - xi, fj, 1 - xj)

                # Also forbid the opposite: cell(fj,ej) is feet and cell(fi,ei) is head
                bad = []
                for xi in (0, 1):
                    for xj in (0, 1):
                        head_i = is_head(xi, ei)
                        feet_j = not is_head(xj, ej)
                        if head_i and feet_j:
                            bad.append((xi, xj))
                for xi, xj in bad:
                    add_clause_or(g, rg, fi, 1 - xi, fj, 1 - xj)

    # Kosaraju
    sys.setrecursionlimit(1_000_000)
    visited = [False] * m
    order = []

    def dfs(v):
        visited[v] = True
        for to in g[v]:
            if not visited[to]:
                dfs(to)
        order.append(v)

    for v in range(m):
        if not visited[v]:
            dfs(v)

    comp = [-1] * m

    def rdfs(v, c):
        comp[v] = c
        for to in rg[v]:
            if comp[to] == -1:
                rdfs(to, c)

    cnum = 0
    for v in reversed(order):
        if comp[v] == -1:
            rdfs(v, cnum)
            cnum += 1

    for i in range(n):
        if comp[2 * i] == comp[2 * i + 1]:
            print("No")
            return

    print("Yes")

