public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (c <= ' ');
            while (c > ' ') {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }

        int nextInt() throws IOException {
            return Integer.parseInt(next());
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        String first = fs.next();
        if (first == null) return;
        int h = Integer.parseInt(first);
        int w = fs.nextInt();

        char[][] g = new char[h][w];
        for (int i = 0; i < h; i++) {
            String s = fs.next();
            g[i] = s.toCharArray();
        }

        // We interpret each futon as two adjacent equal markers.
        // For each futon, one cell is the head and the other is the feet,
        // determined by the direction of the pair in reading order.
        //
        // Bad custom occurs if a feet cell is adjacent (4-neighbor) to another head cell.
        //
        // Since the original statement fragment provided here is incomplete,
        // this implementation follows the standard interpretation for this classic task:
        // check whether every occupied cell belongs to a domino and whether
        // there exists a feet-head adjacency between different dominoes.
        //
        // Occupied cells are any cell not '.'

        int[][] id = new int[h][w];
        for (int[] row : id) Arrays.fill(row, -1);

        List<int[]> heads = new ArrayList<>();
        List<int[]> feet = new ArrayList<>();

        int futonId = 0;

        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                if (g[i][j] == '.' || id[i][j] != -1) continue;

                // Try pair right, then down
                if (j + 1 < w && g[i][j + 1] == g[i][j] && id[i][j + 1] == -1) {
                    id[i][j] = id[i][j + 1] = futonId++;
                    heads.add(new int[]{i, j});
                    feet.add(new int[]{i, j + 1});
                } else if (i + 1 < h && g[i + 1][j] == g[i][j] && id[i + 1][j] == -1) {
                    id[i][j] = id[i + 1][j] = futonId++;
                    heads.add(new int[]{i, j});
                    feet.add(new int[]{i + 1, j});
                } else {
                    System.out.println("No");
                    return;
                }
            }
        }

        int[] dr = {-1, 1, 0, 0};
        int[] dc = {0, 0, -1, 1};

        boolean ok = true;
        for (int k = 0; k < feet.size(); k++) {
            int r = feet.get(k)[0];
            int c = feet.get(k)[1];
            for (int d = 0; d < 4; d++) {
                int nr = r + dr[d];
                int nc = c + dc[d];
                if (nr < 0 || nr >= h || nc < 0 || nc >= w) continue;
                int other = id[nr][nc];
                if (other != -1 && other != k) {
                    int hr = heads.get(other)[0];
                    int hc = heads.get(other)[1];
                    if (hr == nr && hc == nc) {
                        ok = false;
                    }
                }
            }
        }

        System.out.println(ok ? "Yes" : "No");
    }
